'use client'
import { useMemo } from 'react'
import { ConsolePage } from '@/components/product/ConsolePage'
import { EmptyState } from '@/components/ui/EmptyState'
import { PixelButton } from '@/components/ui/PixelButton'
import { Tabs } from '@/components/ui/Tabs'
import { SearchesLog, type SearchOutcome, type SearchPassage, type SearchRow } from '@/components/product/SearchesLog'
import { useControllable } from '@/hooks/useControllable'

// Searches as it ships (pages/dashboard/searches.vue, take 1, Log): what an agent asked and what it read. The page's
// one filter sits in its head (All, Weak match, Nothing found, Failed); the log under it, rows opening in place. With
// no searches yet, the dashed box says where they come from and Connect an agent leads there.
type Show = 'all' | Exclude<SearchOutcome, 'strong'>
export interface SearchesPageProps {
  rows: SearchRow[]
  /** The filter (Vue's v-model:show). */
  show?: Show
  defaultShow?: Show
  onShowChange?: (show: Show) => void
  onConnect?: () => void
  onDownload?: (passage: SearchPassage) => void
  onFix?: (row: SearchRow) => void
  onSearch?: (question: string) => void
}

const FILTERS: Array<{ value: Show, label: string }> = [{ value: 'all', label: 'All' }, { value: 'weak', label: 'Weak match' }, { value: 'none', label: 'Nothing found' }, { value: 'failed', label: 'Failed' }]

export function SearchesPage({ rows, show: showValue, defaultShow = 'all', onShowChange, onConnect, onDownload, onFix, onSearch }: SearchesPageProps) {
  const [show, setShow] = useControllable(showValue, defaultShow, onShowChange)
  const shown = useMemo(() => rows.filter(r => show === 'all' || r.outcome === show), [rows, show])
  return (
    <ConsolePage data-ds="searches-page" title="Searches" actions={rows.length ? <Tabs value={show} onValueChange={setShow} options={FILTERS} label="which searches" /> : undefined}>
      {!rows.length
        ? (
            <EmptyState title="No searches yet" description="Every search your agents run shows here, with what it read.">
              <PixelButton onClick={() => onConnect?.()}>Connect an agent</PixelButton>
            </EmptyState>
          )
        : !shown.length
          ? <p className="type-meta text-fg-muted">No searches like this in the last few hours.</p>
          : (
              <div className="flex flex-col gap-3">
                <SearchesLog rows={shown} onDownload={onDownload} onFix={onFix} onSearch={onSearch} />
              </div>
            )}
    </ConsolePage>
  )
}

export default SearchesPage

'use client'
import { Fragment, useEffect, useRef, useState } from 'react'
import { Check, ChevronDown, Minus, Search, X } from 'lucide-react'
import { cn } from '@/lib/cn'
import { Button } from '@/components/ui/Button'
import { Table } from '@/components/ui/Table'
import { DownloadMark } from '@/components/product/DownloadMark'
import { Transition } from '@/lib/transition'

// Every search, newest first (searches/Log.vue with the Simple detail): the question, the agent, the outcome in
// Performance's words, the time and when, twelve at a time. A row opens in place under itself (180ms both ways on
// the strong ease-out, what's inside fading in and settling 4px), holding what came back: each passage's sentence
// with the part that answers in ink, its document to download, why a search went wrong and what to do about it.
export type SearchOutcome = 'strong' | 'weak' | 'none' | 'failed'
export interface SearchPassage { id: string, namespace: string, text: string, key: string }
export interface SearchRow { id: string, when: string, question: string, agent: string, outcome: SearchOutcome, tookMs: number, passages: SearchPassage[], why?: string, fix?: { action: string } }
export interface SearchesLogProps {
  rows: SearchRow[]
  page?: number
  onDownload?: (passage: SearchPassage) => void
  onFix?: (row: SearchRow) => void
  onSearch?: (question: string) => void
}

const OUTCOME: Record<SearchOutcome, string> = { strong: 'Strong answer', weak: 'Weak match', none: 'Nothing found', failed: 'Failed' }
const took = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)} s` : `${ms} ms`)
const parts = (p: SearchPassage) => {
  const at = p.text.indexOf(p.key)
  return at < 0 ? [p.text, '', ''] : [p.text.slice(0, at), p.key, p.text.slice(at + p.key.length)]
}

export function SearchesLog({ rows, page = 12, onDownload, onFix, onSearch }: SearchesLogProps) {
  const [open, setOpen] = useState('')
  const [shown, setShown] = useState(page)
  // Vue's watch on the rows: a new list closes the open row and shows a page again.
  const first = useRef(true)
  useEffect(() => {
    if (first.current) { first.current = false; return }
    setOpen('')
    setShown(page)
  }, [rows]) // eslint-disable-line react-hooks/exhaustive-deps
  const toggle = (id: string) => setOpen(o => (o === id ? '' : id))
  return (
    <>
      <style href="ds-searches-log" precedence="ds">{css}</style>
      <div data-ds="searches-log" className="overflow-hidden border border-edge bg-surface">
        <Table>
          <thead className="max-sm:sr-only"><tr><th scope="col">Question</th><th scope="col" className="w-40 max-lg:hidden">Agent</th><th scope="col" className="w-44 max-md:hidden">Outcome</th><th scope="col" className="w-20 text-right max-md:hidden">Time</th><th scope="col" className="w-24 text-right max-lg:hidden">When</th><th scope="col" className="w-8"><span className="sr-only">Open</span></th></tr></thead>
          <tbody>
            {rows.slice(0, shown).map(r => (
              <Fragment key={r.id}>
                <tr className="is-link" onClick={() => toggle(r.id)}>
                  <td className="max-w-0 max-sm:w-full">
                    <button type="button" className={cn('block w-full truncate text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-edge-focus max-sm:whitespace-normal', open === r.id && 'whitespace-normal')} aria-expanded={open === r.id} aria-controls={`search-${r.id}`} onClick={(e) => { e.stopPropagation(); toggle(r.id) }}>{r.question}</button>
                    <span className="block truncate type-meta text-fg-muted lg:hidden">{`${r.agent}, ${r.when}`}</span>
                  </td>
                  <td className="max-w-0 truncate max-lg:hidden">{r.agent}</td>
                  <td className="whitespace-nowrap max-md:hidden">
                    <span className={cn('inline-flex items-center gap-1.5', r.outcome !== 'strong' && 'text-home-red-press')}>
                      {r.outcome === 'strong'
                        ? <Check size={12} strokeWidth={2} aria-hidden="true" className="shrink-0" />
                        : r.outcome === 'weak'
                          ? <Minus size={12} strokeWidth={2} aria-hidden="true" className="shrink-0" />
                          : <X size={12} strokeWidth={2} aria-hidden="true" className="shrink-0" />}{OUTCOME[r.outcome]}
                    </span>
                  </td>
                  <td className="text-right tabular-nums max-md:hidden">{took(r.tookMs)}</td>
                  <td className="text-right text-fg-muted max-lg:hidden">{r.when}</td>
                  <td className="text-right"><ChevronDown size={14} strokeWidth={1.5} className="ds-slog-chev inline text-fg-muted" data-open={open === r.id || undefined} aria-hidden="true" /></td>
                </tr>
                <Transition show={open === r.id} name="ds-slog" duration={180}>
                  <tr id={`search-${r.id}`} className="ds-slog-open">
                    <td colSpan={6}>
                      <div className="ds-slog-grow"><div>
                        <div className="flex flex-col gap-3 px-4 pt-3 pb-4">
                          {r.why && <p>{r.why}</p>}
                          {r.passages.length > 0 && (
                            <ul className="flex flex-col gap-2">
                              {r.passages.map(p => (
                                <li key={p.id} className="flex items-center justify-between gap-6 text-fg-soft max-sm:flex-col max-sm:items-start max-sm:gap-0.5">
                                  <p className="min-w-0 flex-1">{parts(p)[0]}<span className="font-medium text-fg">{parts(p)[1]}</span>{parts(p)[2]}</p>
                                  <span className="flex shrink-0 items-center gap-1">
                                    <button type="button" className="ds-slog-doc type-code-sm whitespace-nowrap" aria-label={`download ${p.id}`} onClick={() => onDownload?.(p)}>{p.id}</button>
                                    <DownloadMark id={p.id} onPress={() => onDownload?.(p)} />
                                  </span>
                                </li>
                              ))}
                            </ul>
                          )}
                          <div className="flex flex-wrap gap-2">
                            {r.fix && <Button press onClick={() => onFix?.(r)}>{r.fix.action}</Button>}
                            <Button press onClick={() => onSearch?.(r.question)}><Search size={12} strokeWidth={1.5} aria-hidden="true" />Search it</Button>
                          </div>
                        </div>
                      </div></div>
                    </td>
                  </tr>
                </Transition>
              </Fragment>
            ))}
          </tbody>
        </Table>
      </div>
      {shown < rows.length && <button data-ds="searches-log" type="button" className="ds-slog-more self-start" onClick={() => setShown(s => s + page)}>{`Show ${Math.min(page, rows.length - shown)} more`}</button>}
    </>
  )
}

export default SearchesLog

const css = `
.ds-slog-open > td { height: 0 !important; max-width: 0; padding: 0 !important; background: var(--ds-color-surface-subtle); white-space: normal; }
.ds-slog-open p { margin: 0; }
.ds-slog-grow { display: grid; grid-template-rows: 1fr; }
.ds-slog-grow > div { min-width: 0; min-height: 0; }
:is(.ds-slog-enter-from, .ds-slog-leave-to) .ds-slog-grow { grid-template-rows: 0fr; }
:is(.ds-slog-enter-active, .ds-slog-leave-active) .ds-slog-grow { transition: grid-template-rows var(--ds-duration-slide) var(--ds-easing-out); }
:is(.ds-slog-enter-active, .ds-slog-leave-active) .ds-slog-grow > div { overflow: hidden; }
.ds-slog-enter-active .ds-slog-grow > div { transition: opacity var(--ds-duration-micro) var(--ds-easing-out), transform var(--ds-duration-slide) var(--ds-easing-out); }
.ds-slog-leave-active .ds-slog-grow > div { transition: opacity var(--ds-duration-cell) var(--ds-easing-out); }
.ds-slog-enter-from .ds-slog-grow > div { opacity: 0; transform: translateY(-4px); }
.ds-slog-leave-to .ds-slog-grow > div { opacity: 0; }
/* The chevron turns with the row: 180ms opening, 120ms closing, from where it is. */
.ds-slog-chev { transition: rotate var(--ds-duration-micro) var(--ds-easing-out), color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-slog-chev[data-open] { rotate: 180deg; transition-duration: var(--ds-duration-slide), var(--ds-duration-micro); }
@media (hover: hover) and (pointer: fine) { tr.is-link:hover .ds-slog-chev { color: var(--ds-color-fg); } }
.ds-slog-doc { text-decoration: underline; text-decoration-color: var(--ds-color-edge-strong); text-underline-offset: 3px; transition: text-decoration-color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-slog-doc:hover { text-decoration-color: var(--ds-color-fg); } }
.ds-slog-more { position: relative; margin-left: 4px; color: var(--ds-color-fg-soft); font-size: var(--ds-text-meta); font-weight: var(--ds-font-weight-medium); line-height: var(--ds-text-meta-leading); white-space: nowrap; cursor: pointer; transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-slog-more::after { position: absolute; inset: -12px; content: ""; }
@media (hover: hover) and (pointer: fine) { .ds-slog-more:hover { color: var(--ds-color-fg); } }
.ds-slog-more:focus-visible, .ds-slog-doc:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-focus); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  :is(.ds-slog-enter-active, .ds-slog-leave-active) :is(.ds-slog-grow, .ds-slog-grow > div), .ds-slog-chev { transition: none; }
}
`

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

'use client'
import { Children, cloneElement, isValidElement, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode, type Ref } from 'react'
import { flushSync } from 'react-dom'

// Vue's <Transition> and <TransitionGroup> for the React flavor, with the same class names, so a Vue item's CSS
// (.ds-pop-enter-from, .ds-toast-leave-active, .ds-toast-move...) works unchanged:
//
//   <Transition show={open} name="ds-pop">{<div ... />}</Transition>
//   <TransitionGroup name="ds-toast">{toasts.map((t) => <p key={t.id} ... />)}</TransitionGroup>
//
// Entering: <name>-enter-from and -enter-active, then a frame later -enter-to in place of -enter-from, until the
// transition ends. Leaving: the same with -leave-*, and the element stays until it has, then goes in the same task its
// classes come off (flushSync), so it never shows again for a frame. A group also moves the others with <name>-move
// (FLIP), measured once the entering and leaving children have their classes, as Vue's are. `css={false}` skips the classes (Vue's :css="false"); `duration` is Vue's explicit duration
// in ms, a number or { enter, leave }. The child must take a ref (a DOM element) and className.
type Duration = number | { enter: number, leave: number }
type Phase = 'enter' | 'leave'

const ms = (d: Duration | undefined, phase: Phase) => (d === undefined ? undefined : typeof d === 'number' ? d : d[phase])

/** Runs one Vue transition phase on an element and resolves when it has ended. */
export function runTransition(el: HTMLElement, name: string, phase: Phase, duration?: Duration): Promise<void> {
  const from = `${name}-${phase}-from`
  const active = `${name}-${phase}-active`
  const to = `${name}-${phase}-to`
  el.classList.add(from, active)
  return new Promise((resolve) => {
    let done = false
    const finish = () => {
      if (done) return
      done = true
      el.classList.remove(from, active, to)
      el.removeEventListener('transitionend', onEnd)
      el.removeEventListener('animationend', onEnd)
      resolve()
    }
    const onEnd = (event: Event) => { if (event.target === el) finish() }
    requestAnimationFrame(() => requestAnimationFrame(() => {
      el.classList.remove(from)
      el.classList.add(to)
      const explicit = ms(duration, phase)
      if (explicit !== undefined) return void setTimeout(finish, explicit)
      // The longest transition or animation on it, as Vue reads it; none means done now.
      const cs = getComputedStyle(el)
      const longest = (durations: string, delays: string) => {
        const d = durations.split(',').map(s => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
        const l = delays.split(',').map(s => Number.parseFloat(s) * (s.trim().endsWith('ms') ? 1 : 1000))
        return Math.max(0, ...d.map((x, i) => x + (l[i % l.length] || 0)))
      }
      const total = Math.max(longest(cs.transitionDuration, cs.transitionDelay), longest(cs.animationDuration, cs.animationDelay))
      if (!total) return finish()
      el.addEventListener('transitionend', onEnd)
      el.addEventListener('animationend', onEnd)
      setTimeout(finish, total + 50)
    }))
  })
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T) => {
    for (const r of refs) {
      if (typeof r === 'function') r(node)
      else if (r) (r as { current: T }).current = node
    }
  }
}
type Child = ReactElement<{ ref?: Ref<HTMLElement>, className?: string }>

export interface TransitionProps { show: boolean, name: string, css?: boolean, duration?: Duration, appear?: boolean, children: ReactNode }

/** Vue's <Transition> around one element: it enters when `show` turns true and leaves before it unmounts. */
export function Transition({ show, name, css = true, duration, appear, children }: TransitionProps) {
  // Whether the element is in the page: from the render where `show` turns true until its leave has ended.
  const [present, setPresent] = useState(show)
  const el = useRef<HTMLElement | null>(null)
  const was = useRef<boolean | null>(null)
  const last = useRef<ReactNode>(children)
  if (show) last.current = children
  if (show && !present) setPresent(true)
  useLayoutEffect(() => {
    const before = was.current
    was.current = show
    const node = el.current
    if (before === show) return
    if (show) {
      if (node && css && (before !== null || appear)) void runTransition(node, name, 'enter', duration)
    }
    // Gone in the same task its leave classes come off, as Vue removes it, so no frame shows it whole again.
    else if (node && css && before) void runTransition(node, name, 'leave', duration).then(() => { if (!was.current) flushSync(() => setPresent(false)) })
    else setPresent(false)
  }, [show]) // eslint-disable-line react-hooks/exhaustive-deps
  const child = (show ? children : last.current) as Child
  if (!(show || present) || !isValidElement(child)) return null
  return cloneElement(child, { ref: mergeRefs(child.props.ref, (n: HTMLElement | null) => { el.current = n }) })
}

export interface TransitionGroupProps { name: string, children: ReactNode }

/** Vue's <TransitionGroup>: keyed children enter and leave as <Transition> does, and the rest move with <name>-move. */
export function TransitionGroup({ name, children }: TransitionGroupProps) {
  const nodes = useRef(new Map<string, HTMLElement>())
  const rects = useRef(new Map<string, DOMRect>())
  const seen = useRef(new Set<string>())
  const firstRender = useRef(true)
  const current = Children.toArray(children).filter(isValidElement) as Child[]
  const [leaving, setLeaving] = useState<Map<string, { child: Child, index: number }>>(new Map())
  const prev = useRef<Child[]>([])

  // Children that went away stay, leaving, where they were.
  const keys = new Set(current.map(c => c.key!))
  const gone = prev.current.filter(c => !keys.has(c.key!) && !leaving.has(c.key!))
  if (gone.length) {
    const next = new Map(leaving)
    for (const c of gone) next.set(c.key!, { child: c, index: prev.current.indexOf(c) })
    setLeaving(next)
  }
  prev.current = current
  const list = [...current]
  for (const [key, { child, index }] of leaving) if (!keys.has(key)) list.splice(Math.min(index, list.length), 0, child)

  // Before the DOM changes: where every child is now (for the move).
  for (const [key, node] of nodes.current) rects.current.set(key, node.getBoundingClientRect())

  useLayoutEffect(() => {
    // First every entering and leaving child takes its classes, so the measures for the move below see each as Vue does
    // (an entering one at its enter-from, a leaving one out of the flow): measuring first would fix an entering child's
    // style as it is, fully shown, and its transition would start from the end.
    const entered = new Set<string>()
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node) continue
      if (leaving.has(key)) {
        if (!node.classList.contains(`${name}-leave-active`)) {
          // Gone in the same task its leave classes come off, so no frame shows it whole again.
          void runTransition(node, name, 'leave').then(() => flushSync(() => setLeaving((m) => {
            const n = new Map(m)
            n.delete(key)
            return n
          })))
        }
        continue
      }
      if (!seen.current.has(key)) {
        seen.current.add(key)
        entered.add(key)
        if (!firstRender.current) void runTransition(node, name, 'enter')
      }
    }
    // Then the move: from where each stayed child was to where it is.
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node || leaving.has(key) || entered.has(key)) continue
      const before = rects.current.get(key)
      if (!before) continue
      const after = node.getBoundingClientRect()
      if (before.left !== after.left || before.top !== after.top) {
        node.style.transitionDuration = '0s'
        node.style.transform = `translate(${before.left - after.left}px, ${before.top - after.top}px)`
        void node.offsetWidth
        node.classList.add(`${name}-move`)
        node.style.transitionDuration = ''
        node.style.transform = ''
        const end = () => {
          node.classList.remove(`${name}-move`)
          node.removeEventListener('transitionend', end)
        }
        node.addEventListener('transitionend', end)
      }
    }
    firstRender.current = false
    for (const key of [...seen.current]) if (!list.some(c => c.key === key)) seen.current.delete(key)
  })

  return (
    <>
      {list.map(c => cloneElement(c, {
        key: c.key,
        ref: mergeRefs(c.props.ref, (n: HTMLElement | null) => {
          if (n) nodes.current.set(c.key!, n)
          else nodes.current.delete(c.key!)
        }),
      }))}
    </>
  )
}
